"""hfill A2: VERBATIM copies of the four numba kernels that build the history-similarity xt columns (generated by
extracting the function source with ast from the files named above each kernel; the only change is cache=True -> cache=False
so that nothing is written next to the original files). Constants N_ET = 10, LASTK = 32 as in lab/src/features.py."""
import numba as nb
import numpy as np

N_ET = 10
LASTK = 32

# ---- copied from <repo>/lab/src/features.py :: _emb_feats (lines 48-131)
@nb.njit(parallel=True, fastmath=True, cache=False)
def _emb_feats(cand_off, M, hist_off, H, cemb_idx, hemb_idx, het, user_emb, table, out):
    """out columns:
    0 dot_u, 1 cos_u, 2 item_norm, 3 cos_hall, 4 cos_h10, 5 cos_h50, 6..15 cos_het[1..10],
    16 maxsim32, 17 attn32 (logsumexp(5*cos)/5), 18 mean_sim32, 19 centrality (cos to feed mean),
    20 dot_hall (unnormalized dot with mean hist vec)"""
    n = len(M)
    D = table.shape[1]
    for f in nb.prange(n):
        u = user_emb[f].astype(np.float32)
        un = np.sqrt((u * u).sum()) + 1e-6
        hall = np.zeros(D, np.float32); h10 = np.zeros(D, np.float32); h50 = np.zeros(D, np.float32)
        het_m = np.zeros((N_ET + 1, D), np.float32)
        c_all = 0; c10 = 0; c50 = 0
        het_c = np.zeros(N_ET + 1, np.int64)
        ho = hist_off[f]
        nk = 0
        lastk = np.zeros((LASTK, D), np.float32)
        for j in range(H[f]):
            ei = hemb_idx[ho + j]
            if ei < 0:
                continue
            v = table[ei].astype(np.float32)
            vn = np.sqrt((v * v).sum()) + 1e-6
            v = v / vn
            hall += v; c_all += 1
            if j < 10:
                h10 += v; c10 += 1
            if j < 50:
                h50 += v; c50 += 1
            et = het[ho + j]
            if 0 < et <= N_ET:
                het_m[et] += v; het_c[et] += 1
            if nk < LASTK:
                lastk[nk] = v; nk += 1
        # normalize pooled vectors
        hn = np.sqrt((hall * hall).sum()); h10n = np.sqrt((h10 * h10).sum()); h50n = np.sqrt((h50 * h50).sum())
        hetn = np.zeros(N_ET + 1, np.float32)
        for e in range(1, N_ET + 1):
            hetn[e] = np.sqrt((het_m[e] * het_m[e]).sum())
        co = cand_off[f]
        m = M[f]
        cmean = np.zeros(D, np.float32)
        cvecs = np.zeros((m, D), np.float32)
        for i in range(m):
            ei = cemb_idx[co + i]
            if ei < 0:
                for k in range(21):
                    out[co + i, k] = np.nan
                continue
            v = table[ei].astype(np.float32)
            vn = np.sqrt((v * v).sum()) + 1e-6
            dot = (v * u).sum()
            out[co + i, 0] = dot
            out[co + i, 1] = dot / (vn * un)
            out[co + i, 2] = vn
            v = v / vn
            cvecs[i] = v
            cmean += v
            out[co + i, 3] = (v * hall).sum() / hn if hn > 0 else np.nan
            out[co + i, 4] = (v * h10).sum() / h10n if h10n > 0 else np.nan
            out[co + i, 5] = (v * h50).sum() / h50n if h50n > 0 else np.nan
            for e in range(1, N_ET + 1):
                out[co + i, 5 + e] = (v * het_m[e]).sum() / hetn[e] if hetn[e] > 0 else np.nan
            if nk > 0:
                mx = -2.0; se = 0.0; sm = 0.0
                for k in range(nk):
                    s = (v * lastk[k]).sum()
                    if s > mx:
                        mx = s
                    se += np.exp(5.0 * s)
                    sm += s
                out[co + i, 16] = mx
                out[co + i, 17] = np.log(se) / 5.0
                out[co + i, 18] = sm / nk
            else:
                out[co + i, 16] = np.nan; out[co + i, 17] = np.nan; out[co + i, 18] = np.nan
            out[co + i, 20] = (v * hall).sum() / c_all if c_all > 0 else np.nan
        cmn = np.sqrt((cmean * cmean).sum())
        for i in range(m):
            if cemb_idx[co + i] >= 0 and cmn > 0:
                out[co + i, 19] = (cvecs[i] * cmean).sum() / cmn
            else:
                out[co + i, 19] = np.nan


# ---- copied from <repo>/lab/feats_v2/ctx_/build_ctx.py :: _nd_kernel (lines 239-379)
@nb.njit(parallel=True, fastmath=True, cache=False)
def _nd_kernel(cand_off, M, hist_off, H, cemb, hemb, table, user_emb, cos_u, maxsim, f1, feed_out, out):
    """out columns:
    0 nd_max, 1 nd_c80, 2 nd_c90, 3 nd_c95, 4 nd_mean, 5 nd_top5u, 6 nd_top5h,
    7 nd_knn_u, 8 nd_knn_h, 9 nd_knn_f1, 10 nd_dup_better_h, 11 nd_dup_better_f1, 12 nd_dup_better_u,
    13 nd_ucent (cos(c,u) - cos(c,feedmean)), 14 nd_hcent (cos(c,h10) - cos(c,feedmean)),
    15 nd_knn_u_dev (cos_u - knn_u), 16 nd_knn_h_dev, 17 nd_max_samecat_gap (max cos to other-cat minus same-cat)
    feed_out: 0 mean pairwise cos, 1 share of pairs with cos > .9, 2 cos(user, feed mean), 3 cos(h10, feed mean)"""
    n = len(M)
    D = table.shape[1]
    for f in nb.prange(n):
        co = cand_off[f]
        m = M[f]
        V = np.zeros((m, D), np.float32)
        ok = np.zeros(m, np.bool_)
        fm = np.zeros(D, np.float32)
        for i in range(m):
            ei = cemb[co + i]
            if ei < 0:
                continue
            v = table[ei].astype(np.float32)
            nv = np.sqrt((v * v).sum()) + 1e-6
            V[i] = v / nv
            ok[i] = True
            fm += V[i]
        fmn = np.sqrt((fm * fm).sum())
        if fmn > 0:
            fm = fm / fmn
        u = user_emb[f].astype(np.float32)
        un = np.sqrt((u * u).sum())
        uok = un > 0
        if uok:
            u = u / un
        h = np.zeros(D, np.float32)
        ho = hist_off[f]
        nh = 0
        for j in range(H[f]):
            ei = hemb[ho + j]
            if ei < 0:
                continue
            v = table[ei].astype(np.float32)
            nv = np.sqrt((v * v).sum()) + 1e-6
            h += v / nv
            nh += 1
            if nh >= 10:
                break
        hn = np.sqrt((h * h).sum())
        hok = hn > 0
        if hok:
            h = h / hn
        S = V @ V.T
        # top-5 by cos_u and by maxsim
        cu = np.empty(m); ch = np.empty(m)
        for i in range(m):
            # verifier fix: a zero user vector gives cos_u == 0 (not NaN) for every candidate -> treat as missing
            # (otherwise top-5-by-cos_u is an arbitrary tie order and knn_u / knn_u_dev collapse to a fake 0)
            cu[i] = cos_u[co + i] if (ok[i] and uok and not np.isnan(cos_u[co + i])) else -9.0
            ch[i] = maxsim[co + i] if (ok[i] and not np.isnan(maxsim[co + i])) else -9.0
        ou = np.argsort(-cu)
        oh = np.argsort(-ch)
        npair = 0; spair = 0.0; p90 = 0
        for i in range(m):
            if not ok[i]:
                for k in range(18):
                    out[co + i, k] = np.nan
                continue
            mx = -2.0; c80 = 0; c90 = 0; c95 = 0; sm = 0.0; no = 0
            wsu = 0.0; wsh = 0.0; wsf = 0.0; wu = 0.0; wh = 0.0; wf = 0.0
            bh = 0; bf = 0; bu = 0
            mx_same = -2.0; mx_oth = -2.0
            for j in range(m):
                if j == i or not ok[j]:
                    continue
                s = S[i, j]
                no += 1
                sm += s
                if s > mx:
                    mx = s
                if s > 0.8:
                    c80 += 1
                if s > 0.9:
                    c90 += 1
                    if maxsim[co + j] > maxsim[co + i]:
                        bh += 1
                    if f1[co + j] > f1[co + i]:
                        bf += 1
                    if cos_u[co + j] > cos_u[co + i]:
                        bu += 1
                if s > 0.95:
                    c95 += 1
                w = np.exp(20.0 * (s - 1.0))
                if uok and not np.isnan(cos_u[co + j]):
                    wsu += w * cos_u[co + j]; wu += w
                if not np.isnan(maxsim[co + j]):
                    wsh += w * maxsim[co + j]; wh += w
                if not np.isnan(f1[co + j]):
                    wsf += w * f1[co + j]; wf += w
                if j > i:
                    npair += 1; spair += s
                    if s > 0.9:
                        p90 += 1
            out[co + i, 0] = mx if no > 0 else np.nan
            out[co + i, 1] = c80
            out[co + i, 2] = c90
            out[co + i, 3] = c95
            out[co + i, 4] = sm / no if no > 0 else np.nan
            # top-5 by cos_u excluding self
            t = 0; st = 0.0
            for r in range(m):
                j = ou[r]
                if j == i or cu[j] < -5:
                    continue
                st += S[i, j]; t += 1
                if t >= 5:
                    break
            out[co + i, 5] = st / t if t > 0 else np.nan
            t = 0; st = 0.0
            for r in range(m):
                j = oh[r]
                if j == i or ch[j] < -5:
                    continue
                st += S[i, j]; t += 1
                if t >= 5:
                    break
            out[co + i, 6] = st / t if t > 0 else np.nan
            out[co + i, 7] = wsu / wu if wu > 0 else np.nan
            out[co + i, 8] = wsh / wh if wh > 0 else np.nan
            out[co + i, 9] = wsf / wf if wf > 0 else np.nan
            out[co + i, 10] = bh
            out[co + i, 11] = bf
            out[co + i, 12] = bu
            cfm = (V[i] * fm).sum()
            out[co + i, 13] = (V[i] * u).sum() - cfm if uok else np.nan
            out[co + i, 14] = (V[i] * h).sum() - cfm if hok else np.nan
            out[co + i, 15] = cos_u[co + i] - out[co + i, 7]
            out[co + i, 16] = maxsim[co + i] - out[co + i, 8]
            out[co + i, 17] = np.nan
        feed_out[f, 0] = spair / npair if npair > 0 else np.nan
        feed_out[f, 1] = p90 / npair if npair > 0 else np.nan
        feed_out[f, 2] = (u * fm).sum() if (uok and fmn > 0) else np.nan
        feed_out[f, 3] = (h * fm).sum() if (hok and fmn > 0) else np.nan


# ---- copied from <repo>/lab/feats_v2/ctx_/build_ctx3.py :: _hn_kernel (lines 26-108)
@nb.njit(parallel=True, fastmath=True, cache=False)
def _hn_kernel(cand_off, M, hist_off, H, cemb, hemb, hmask, table, K, decay, out):
    D = table.shape[1]
    for f in nb.prange(len(M)):
        co = cand_off[f]; m = M[f]
        Hm = np.zeros((K, D), np.float32)  # K is a runtime argument
        nk = 0
        ho = hist_off[f]
        for j in range(H[f]):
            ei = hemb[ho + j]
            if ei < 0 or not hmask[ho + j]:
                continue
            v = table[ei].astype(np.float32)
            Hm[nk] = v / (np.sqrt((v * v).sum()) + 1e-6)
            nk += 1
            if nk >= K:
                break
        V = np.zeros((m, D), np.float32)
        ok = np.zeros(m, np.bool_)
        for i in range(m):
            ei = cemb[co + i]
            if ei >= 0:
                v = table[ei].astype(np.float32)
                V[i] = v / (np.sqrt((v * v).sum()) + 1e-6)
                ok[i] = True
        if nk == 0:
            for i in range(m):
                for c in range(8):
                    out[co + i, c] = np.nan
            continue
        S = V @ Hm[:nk].T  # m x nk
        for i in range(m):
            if not ok[i]:
                for j in range(nk):
                    S[i, j] = -9.0
        top1 = np.zeros(m); top1w = np.zeros(m); top3w = np.zeros(m); rrw = np.zeros(m)
        s05 = np.zeros(m); s02 = np.zeros(m)
        wsum = 0.0
        # per history item: ranks of candidates
        R = np.zeros((m, nk), np.int32)
        best_other = np.zeros((m, nk), np.float32)  # best similarity among other candidates
        for j in range(nk):
            w = decay ** j
            wsum += w
            col = S[:, j].copy()
            o = np.argsort(-col)
            for r in range(m):
                R[o[r], j] = r
            b1 = col[o[0]]
            b2 = col[o[1]] if m > 1 else -9.0
            for i in range(m):
                best_other[i, j] = b2 if i == o[0] else b1
            i0 = o[0]
            top1[i0] += 1; top1w[i0] += w
            for r in range(min(3, m)):
                top3w[o[r]] += w
            for i in range(m):
                rrw[i] += w / (1.0 + R[i, j])
            z05 = 0.0; z02 = 0.0
            for i in range(m):
                if ok[i]:
                    z05 += np.exp((col[i] - b1) / 0.05); z02 += np.exp((col[i] - b1) / 0.02)
            for i in range(m):
                if ok[i]:
                    s05[i] += w * np.exp((col[i] - b1) / 0.05) / z05
                    s02[i] += w * np.exp((col[i] - b1) / 0.02) / z02
        for i in range(m):
            if not ok[i]:
                for c in range(8):
                    out[co + i, c] = np.nan
                continue
            jb = 0
            for j in range(1, nk):
                if S[i, j] > S[i, jb]:
                    jb = j
            out[co + i, 0] = top1[i]
            out[co + i, 1] = top1w[i] / wsum
            out[co + i, 2] = top3w[i] / wsum
            out[co + i, 3] = rrw[i] / wsum
            out[co + i, 4] = R[i, jb] / (m - 1) if m > 1 else 0.0
            out[co + i, 5] = S[i, jb] - best_other[i, jb]
            out[co + i, 6] = s05[i] / wsum * m
            out[co + i, 7] = s02[i] / wsum * m


# ---- copied from <repo>/lab/feats_v2/ctx_/build_ctx4.py :: _hs_kernel (lines 30-93)
@nb.njit(parallel=True, fastmath=True, cache=False)
def _hs_kernel(cand_off, M, hist_off, H, cemb, hemb, hmask, table, K, decay, tau, out_mass, out_mutual):
    D = table.shape[1]
    for f in nb.prange(len(M)):
        co = cand_off[f]; m = M[f]
        Hm = np.zeros((K, D), np.float32)
        nk = 0
        ho = hist_off[f]
        for j in range(H[f]):
            ei = hemb[ho + j]
            if ei < 0 or not hmask[ho + j]:
                continue
            v = table[ei].astype(np.float32)
            Hm[nk] = v / (np.sqrt((v * v).sum()) + 1e-6)
            nk += 1
            if nk >= K:
                break
        V = np.zeros((m, D), np.float32)
        ok = np.zeros(m, np.bool_)
        for i in range(m):
            ei = cemb[co + i]
            if ei >= 0:
                v = table[ei].astype(np.float32)
                V[i] = v / (np.sqrt((v * v).sum()) + 1e-6)
                ok[i] = True
        if nk == 0:
            for i in range(m):
                out_mass[co + i] = np.nan; out_mutual[co + i] = np.nan
            continue
        S = V @ Hm[:nk].T
        mass = np.zeros(m); mut = np.zeros(m)
        # nearest history item of each candidate
        hbest = np.zeros(m, np.int64)
        for i in range(m):
            b = 0
            for j in range(1, nk):
                if S[i, j] > S[i, b]:
                    b = j
            hbest[i] = b
        wsum = 0.0
        for j in range(nk):
            w = decay ** j
            wsum += w
            b1 = -9.0; ib = -1
            for i in range(m):
                if ok[i] and S[i, j] > b1:
                    b1 = S[i, j]; ib = i
            if ib < 0:
                continue
            z = 0.0
            for i in range(m):
                if ok[i]:
                    z += np.exp((S[i, j] - b1) / tau)
            for i in range(m):
                if ok[i]:
                    mass[i] += w * np.exp((S[i, j] - b1) / tau) / z
            if hbest[ib] == j:
                mut[ib] += w
        for i in range(m):
            if ok[i]:
                out_mass[co + i] = mass[i] / wsum * m
                out_mutual[co + i] = mut[i] / wsum
            else:
                out_mass[co + i] = np.nan; out_mutual[co + i] = np.nan

